package edu.gcu.cst339.lab2_chinook_api.album;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object used as the JSON request and response body for albums.
 *
 * <p>Keeping a separate DTO means the API contract does not change if the JPA
 * entity changes, and the validation annotations here are checked on create
 * and update requests before any database work happens.</p>
 *
 * @param albumId  the album ID; generated by the database, so it is ignored on
 *                 create and taken from the URL on update
 * @param title    the album title; required, at most 160 characters
 * @param artistId the ID of the artist who recorded the album; required and must
 *                 reference an existing artist
 */
public record AlbumDto(
    Integer albumId,

    @NotBlank
    @Size(max = 160)
    String title,

    @NotNull
    Integer artistId) {
        
    /**
     * Converts an album entity into a DTO.
     *
     * @param album the entity to convert
     * @return a DTO containing the entity's ID, title and artist ID
     */
    static AlbumDto fromEntity(Album album) {
        return new AlbumDto(
            album.getAlbumId(),
            album.getTitle(),
            album.getArtistId()
        );
    }
}
